import './Footer.css';

function Footer() {
  return (
    <footer className="footer">
      <div className="container">
        <p>&copy; 2026 Crescent Academia Moot 2.0. All rights reserved.</p>
        <p>Organized by Crescent Girls | The Crescent College Lahore, Girls Campus</p>
      </div>
    </footer>
  );
}

export default Footer;
